import express, { type Express, type Request, type Response } from "express";
import { z } from "zod/v4";
import { config } from "./config";
import { QuotaService } from "./quota";
import { logger } from "./logger";

/** Client identity. The device id is generated by the app and persisted locally. */
function deviceIdOf(req: Request): string {
  const raw = req.header("x-pathforge-device")?.trim() ?? "";
  return /^[A-Za-z0-9_-]{8,128}$/.test(raw) ? raw : "";
}

function clientIp(req: Request): string {
  // Behind an ingress/LB the real address is the first XFF hop.
  const forwarded = req.header("x-forwarded-for")?.split(",")[0]?.trim();
  return forwarded || req.socket.remoteAddress || "unknown";
}

/**
 * Validates the fields this service governs (model, size) and lets the rest of
 * an OpenAI-compatible body through — SDKs add fields over time, and rejecting
 * unknown keys would break real clients for no security gain, since the model
 * allowlist and token clamp below are what actually bound cost.
 */
const ChatBody = z.object({
  model: z.string().min(1),
  messages: z.array(z.record(z.string(), z.unknown())).min(1),
  stream: z.boolean().optional(),
  max_tokens: z.number().int().positive().optional(),
});

function estimateTokens(body: unknown, output: string): number {
  // Fallback when the provider does not report usage: ~4 chars per token.
  return Math.ceil((JSON.stringify(body ?? "").length + output.length) / 4);
}

/** OpenRouter reports both totals; cost is authoritative for the spend caps. */
interface UpstreamUsage {
  total_tokens?: number;
  cost?: number;
}

function usageFrom(reported: UpstreamUsage | undefined, fallbackTokens: number) {
  return {
    tokens: reported?.total_tokens ?? fallbackTokens,
    costMicros: Math.round((reported?.cost ?? 0) * 1_000_000),
  };
}

export function createApp(quota: QuotaService): Express {
  const app = express();
  app.set("trust proxy", true);
  app.use(express.json({ limit: "2mb" }));

  app.get("/healthz", (_req, res) => {
    res.json({ status: "ok" });
  });

  // Lets the app show "x requests left today" and nudge the user to add their key.
  app.get("/v1/quota", async (req, res) => {
    const deviceId = deviceIdOf(req);
    if (!deviceId) {
      res.status(400).json({ error: "Missing or malformed x-pathforge-device header" });
      return;
    }
    res.json(await quota.snapshot(deviceId, clientIp(req)));
  });

  app.post("/v1/chat/completions", async (req: Request, res: Response): Promise<void> => {
    // 1. Identify + authorize
    if (config.appKey && req.header("x-pathforge-app-key") !== config.appKey) {
      res.status(401).json({ error: "Unauthorized" });
      return;
    }
    const deviceId = deviceIdOf(req);
    if (!deviceId) {
      res.status(400).json({ error: "Missing or malformed x-pathforge-device header" });
      return;
    }
    const ip = clientIp(req);

    // 2. Validate the request shape and clamp what it may ask for
    const parsed = ChatBody.safeParse(req.body);
    if (!parsed.success) {
      res.status(400).json({ error: `Unsupported request: ${parsed.error.message}` });
      return;
    }
    if (!config.allowedModels.includes(parsed.data.model)) {
      res.status(400).json({ error: `Model not allowed on the free tier: ${parsed.data.model}` });
      return;
    }
    const body = {
      ...(req.body as Record<string, unknown>),
      model: parsed.data.model,
      max_tokens: Math.min(parsed.data.max_tokens ?? config.maxTokensPerRequest, config.maxTokensPerRequest),
      // Ask the provider to report real usage, including on streamed responses.
      usage: { include: true },
    };

    // 3. Quota
    const decision = await quota.check(deviceId, ip);
    if (!decision.allowed) {
      res.setHeader("Retry-After", String(decision.retryAfterSeconds));
      res.status(429).json({
        error: "Free daily limit reached",
        reason: decision.reason,
        retryAfterSeconds: decision.retryAfterSeconds,
        hint: "Add your own OpenRouter API key in Settings to keep going without limits.",
      });
      return;
    }

    // 4. Forward upstream — the key never leaves this process
    const upstream = await fetch(`${config.openRouterBaseUrl}/chat/completions`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${config.openRouterApiKey}`,
      },
      body: JSON.stringify(body),
    }).catch((err: unknown) => {
      logger.error({ err }, "upstream request failed");
      return null;
    });

    if (!upstream) {
      res.status(502).json({ error: "Upstream request failed" });
      return;
    }
    if (!upstream.ok || !upstream.body) {
      const detail = await upstream.text().catch(() => "");
      logger.warn({ status: upstream.status, detail: detail.slice(0, 300) }, "upstream error");
      res.status(upstream.status === 429 ? 429 : 502).json({
        error: "Upstream error",
        status: upstream.status,
      });
      return;
    }

    // 5a. Non-streaming: forward the JSON and meter the reported usage
    if (!parsed.data.stream) {
      const json = (await upstream.json()) as { usage?: UpstreamUsage };
      const used = usageFrom(json.usage, estimateTokens(body, JSON.stringify(json)));
      await quota.record(deviceId, ip, used);
      logger.info({ deviceId, ...used, streamed: false }, "served free-tier request");
      res.json(json);
      return;
    }

    // 5b. Streaming: pipe SSE through untouched (tool calls included) while
    // watching for the usage chunk so metering stays accurate.
    res.setHeader("Content-Type", "text/event-stream");
    res.setHeader("Cache-Control", "no-cache");
    res.setHeader("Connection", "keep-alive");
    res.setHeader("X-Accel-Buffering", "no");
    res.flushHeaders();

    const reader = upstream.body.getReader();
    const decoder = new TextDecoder();
    let buffered = "";
    let reportedUsage: UpstreamUsage | undefined;
    let streamedChars = 0;

    // If the client hangs up, stop pulling from upstream so we stop paying for it.
    let aborted = false;
    res.on("close", () => {
      aborted = true;
      void reader.cancel().catch(() => {});
    });

    try {
      while (!aborted) {
        const { done, value } = await reader.read();
        if (done) break;
        const text = decoder.decode(value, { stream: true });
        streamedChars += text.length;
        res.write(text);

        // Usage arrives in a late chunk; scan line-wise without buffering the whole stream.
        buffered = (buffered + text).slice(-8000);
        for (const line of buffered.split("\n")) {
          if (!line.startsWith("data:")) continue;
          const payload = line.slice(5).trim();
          if (!payload || payload === "[DONE]") continue;
          try {
            const parsedChunk = JSON.parse(payload) as { usage?: UpstreamUsage };
            if (parsedChunk.usage?.total_tokens) reportedUsage = parsedChunk.usage;
          } catch {
            // partial JSON across chunk boundaries — ignore
          }
        }
      }
    } catch (err) {
      logger.warn({ err }, "stream interrupted");
    } finally {
      const used = usageFrom(reportedUsage, estimateTokens(body, "x".repeat(streamedChars)));
      await quota.record(deviceId, ip, used).catch(() => {});
      logger.info({ deviceId, ...used, streamed: true }, "served free-tier request");
      if (!res.writableEnded) res.end();
    }
  });

  return app;
}
